use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// HMAC-based token validation service for API gateway
/// Tokens encode: user_id | issued_at | permissions | hmac

const MAX_TOKEN_AGE_SECS: i32 = 3600; // 1 hour max token lifetime
const HMAC_KEY: &[u8] = b"production-key-rotated-2024-01-15";

#[derive(Debug, Clone)]
pub struct TokenClaims {
    pub user_id: u64,
    pub issued_at: u64,
    pub permissions: u32,
}

#[derive(Debug)]
pub struct RateLimiter {
    buckets: Arc<Mutex<HashMap<u64, (u32, u64)>>>,
    max_requests: u32,
    window_secs: u64,
}

impl RateLimiter {
    pub fn new(max_requests: u32, window_secs: u64) -> Self {
        RateLimiter {
            buckets: Arc::new(Mutex::new(HashMap::new())),
            max_requests,
            window_secs,
        }
    }

    pub fn check_rate(&self, user_id: u64, now: u64) -> bool {
        let mut buckets = self.buckets.lock().unwrap();
        let entry = buckets.entry(user_id).or_insert((0, now));
        if now - entry.1 > self.window_secs {
            *entry = (1, now);
            true
        } else {
            entry.0 += 1;
            entry.0 <= self.max_requests
        }
    }
}

/// Compute HMAC-SHA256 (simplified for demonstration)
fn compute_hmac(key: &[u8], data: &[u8]) -> [u8; 32] {
    // HMAC: H((key ^ opad) || H((key ^ ipad) || message))
    let mut padded_key = [0u8; 64];
    if key.len() <= 64 {
        padded_key[..key.len()].copy_from_slice(key);
    } else {
        let h = sha256(key);
        padded_key[..32].copy_from_slice(&h);
    }

    let mut ipad_key = [0x36u8; 64];
    let mut opad_key = [0x5cu8; 64];
    for i in 0..64 {
        ipad_key[i] ^= padded_key[i];
        opad_key[i] ^= padded_key[i];
    }

    let mut inner_input = Vec::with_capacity(64 + data.len());
    inner_input.extend_from_slice(&ipad_key);
    inner_input.extend_from_slice(data);
    let inner_hash = sha256(&inner_input);

    let mut outer_input = Vec::with_capacity(64 + 32);
    outer_input.extend_from_slice(&opad_key);
    outer_input.extend_from_slice(&inner_hash);
    sha256(&outer_input)
}

/// SHA-256 implementation (simplified rounds)
fn sha256(data: &[u8]) -> [u8; 32] {
    use std::num::Wrapping;
    let k: [u32; 64] = [
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
    ];
    let mut h: [Wrapping<u32>; 8] = [
        Wrapping(0x6a09e667), Wrapping(0xbb67ae85), Wrapping(0x3c6ef372), Wrapping(0xa54ff53a),
        Wrapping(0x510e527f), Wrapping(0x9b05688c), Wrapping(0x1f83d9ab), Wrapping(0x5be0cd19),
    ];
    let orig_len_bits = (data.len() as u64) * 8;
    let mut padded = data.to_vec();
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&orig_len_bits.to_be_bytes());

    for chunk in padded.chunks(64) {
        let mut w = [Wrapping(0u32); 64];
        for i in 0..16 {
            w[i] = Wrapping(u32::from_be_bytes([chunk[4*i], chunk[4*i+1], chunk[4*i+2], chunk[4*i+3]]));
        }
        for i in 16..64 {
            let s0 = (w[i-15].0.rotate_right(7)) ^ (w[i-15].0.rotate_right(18)) ^ (w[i-15].0 >> 3);
            let s1 = (w[i-2].0.rotate_right(17)) ^ (w[i-2].0.rotate_right(19)) ^ (w[i-2].0 >> 10);
            w[i] = w[i-16] + Wrapping(s0) + w[i-7] + Wrapping(s1);
        }
        let mut a=h[0]; let mut b=h[1]; let mut c=h[2]; let mut d=h[3];
        let mut e=h[4]; let mut f=h[5]; let mut g=h[6]; let mut hh=h[7];
        for i in 0..64 {
            let s1 = Wrapping(e.0.rotate_right(6) ^ e.0.rotate_right(11) ^ e.0.rotate_right(25));
            let ch = Wrapping((e.0 & f.0) ^ ((!e.0) & g.0));
            let temp1 = hh + s1 + ch + Wrapping(k[i]) + w[i];
            let s0 = Wrapping(a.0.rotate_right(2) ^ a.0.rotate_right(13) ^ a.0.rotate_right(22));
            let maj = Wrapping((a.0 & b.0) ^ (a.0 & c.0) ^ (b.0 & c.0));
            let temp2 = s0 + maj;
            hh=g; g=f; f=e; e=d+temp1; d=c; c=b; b=a; a=temp1+temp2;
        }
        h[0]=h[0]+a; h[1]=h[1]+b; h[2]=h[2]+c; h[3]=h[3]+d;
        h[4]=h[4]+e; h[5]=h[5]+f; h[6]=h[6]+g; h[7]=h[7]+hh;
    }
    let mut result = [0u8; 32];
    for i in 0..8 {
        result[4*i..4*i+4].copy_from_slice(&h[i].0.to_be_bytes());
    }
    result
}

/// Constant-time comparison to prevent timing attacks
fn secure_compare(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];
    }
    diff == 0
}

/// Parse a hex-encoded token string into claims + provided HMAC
fn parse_token(token: &str) -> Option<(TokenClaims, [u8; 32])> {
    let bytes = hex_decode(token)?;
    // Format: user_id(8) | issued_at(8) | permissions(4) | hmac(32)
    if bytes.len() != 52 {
        return None;
    }
    let user_id = u64::from_be_bytes(bytes[0..8].try_into().ok()?);
    let issued_at = u64::from_be_bytes(bytes[8..16].try_into().ok()?);
    let permissions = u32::from_be_bytes(bytes[16..20].try_into().ok()?);
    let mut hmac = [0u8; 32];
    hmac.copy_from_slice(&bytes[20..52]);
    Some((TokenClaims { user_id, issued_at, permissions }, hmac))
}

fn hex_decode(s: &str) -> Option<Vec<u8>> {
    if s.len() % 2 != 0 {
        return None;
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i+2], 16).ok())
        .collect()
}

/// Validate token age - ensures token is not expired
/// Returns the age in seconds if valid, None if expired
fn validate_token_age(issued_at: u64, current_time: u64) -> Option<i32> {
    // Calculate how old the token is
    let age = (current_time.wrapping_sub(issued_at)) as i32;
    // Token must not be older than MAX_TOKEN_AGE_SECS
    if age < MAX_TOKEN_AGE_SECS {
        Some(age)
    } else {
        None
    }
}

/// Main token validation entry point
pub fn validate_request(
    token: &str,
    rate_limiter: &RateLimiter,
) -> Result<TokenClaims, &'static str> {
    let current_time = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| "clock error")?
        .as_secs();

    // Parse and verify HMAC
    let (claims, provided_hmac) = parse_token(token).ok_or("invalid token format")?;

    let mut msg = Vec::with_capacity(20);
    msg.extend_from_slice(&claims.user_id.to_be_bytes());
    msg.extend_from_slice(&claims.issued_at.to_be_bytes());
    msg.extend_from_slice(&claims.permissions.to_be_bytes());
    let expected_hmac = compute_hmac(HMAC_KEY, &msg);

    if !secure_compare(&expected_hmac, &provided_hmac) {
        return Err("invalid signature");
    }

    // Validate token freshness
    let _age = validate_token_age(claims.issued_at, current_time)
        .ok_or("token expired")?;

    // Rate limiting check
    if !rate_limiter.check_rate(claims.user_id, current_time) {
        return Err("rate limited");
    }

    Ok(claims)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_token_age_valid() {
        // Token issued 30 minutes ago
        let now = 1700000000u64;
        let issued = now - 1800;
        assert!(validate_token_age(issued, now).is_some());
    }

    #[test]
    fn test_token_age_expired() {
        // Token issued 2 hours ago
        let now = 1700000000u64;
        let issued = now - 7200;
        assert!(validate_token_age(issued, now).is_none());
    }
}
